import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [items, setItems] = useState([
    { id: 'a', label: 'Apple' },
    { id: 'b', label: 'Banana' },
    { id: 'c', label: 'Cherry' },
  ]);

  const reverse = () => setItems([...items].reverse());

  return (
    <div>
      <button id="reverse" onClick={reverse}>Reverse</button>
      <ul id="list">
        {items.map((item, i) => (
          <li key={i}>
            <input id={'input-' + item.id} defaultValue={item.label} />
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;

