import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Wandering Edit', () => {
  test('List and reverse button render', async () => {
    const { container: root } = render(<App />);
    if (!root.querySelector('#reverse')) throw new Error('No #reverse button found');
const lis = root.querySelectorAll('#list li');
if (lis.length !== 3) throw new Error('Expected 3 list items, got ' + lis.length);
  });

  test('Typed text follows its item after a reorder', async () => {
    const { container: root } = render(<App />);
    const a = root.querySelector('#input-a');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(a, 'Apple Pie');
a.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
root.querySelector('#reverse').click();
await tick();
const aAfter = root.querySelector('#input-a');
const cAfter = root.querySelector('#input-c');
if (!aAfter) throw new Error('Lost #input-a after reorder');
if (aAfter.value !== 'Apple Pie')
  throw new Error('The Apple input should still hold "Apple Pie" after reverse — got "' + aAfter.value + '"');
if (cAfter.value === 'Apple Pie')
  throw new Error('The edit leaked onto the Cherry input — key is tied to position, not identity');
  });
});
